  1	import java.util.ArrayList;
  2	import java.util.Comparator;
  3	import java.util.Objects;
  4	import java.util.PriorityQueue;
  5	
  6	class HuffmanCoding {
  7	
  8	    private static final int INTERNAL_NODE_SYMBOL_INDEX = -1;
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	
 11	    private static final Comparator<Node> NODE_ORDER = Comparator
 12	            .comparingLong((Node node) -> node.frequency)
 13	            .thenComparingInt(node -> node.firstSymbolIndex);
 14	
 15	    private HuffmanCoding() {
 16	    }
 17	
 18	    private static final class Node {
 19	        private final long frequency;
 20	        private final int firstSymbolIndex;
 21	        private final int symbolIndex;
 22	        private final Node left;
 23	        private final Node right;
 24	
 25	        private Node(int frequency, int symbolIndex) {
 26	            this.frequency = frequency;
 27	            this.firstSymbolIndex = symbolIndex;
 28	            this.symbolIndex = symbolIndex;
 29	            this.left = null;
 30	            this.right = null;
 31	        }
 32	
 33	        private Node(Node left, Node right) {
 34	            this.frequency = left.frequency + right.frequency;
 35	            this.firstSymbolIndex = Math.min(left.firstSymbolIndex, right.firstSymbolIndex);
 36	            this.symbolIndex = INTERNAL_NODE_SYMBOL_INDEX;
 37	            this.left = left;
 38	            this.right = right;
 39	        }
 40	
 41	        private boolean isLeaf() {
 42	            return left == null && right == null;
 43	        }
 44	    }
 45	
 46	    private interface LeafCodeConsumer {
 47	        void accept(Node leaf, String code);
 48	    }
 49	
 50	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 51	        Node root = buildTreeFor(symbols, frequencies);
 52	        return collectCodesInTraversalOrder(root, symbols.length());
 53	    }
 54	
 55	    static ArrayList<String> huffmanCodesBySymbol(String symbols, int[] frequencies) {
 56	        Node root = buildTreeFor(symbols, frequencies);
 57	        return collectCodesBySymbolOrder(root, symbols.length());
 58	    }
 59	
 60	    private static void validateInput(String symbols, int[] frequencies) {
 61	        Objects.requireNonNull(symbols, "Input string must not be null");
 62	        Objects.requireNonNull(frequencies, "Frequency array must not be null");
 63	
 64	        if (symbols.length() != frequencies.length) {
 65	            throw new IllegalArgumentException("Input string and frequency array must have the same length");
 66	        }
 67	    }
 68	
 69	    private static Node buildTreeFor(String symbols, int[] frequencies) {
 70	        validateInput(symbols, frequencies);
 71	
 72	        if (symbols.isEmpty()) {
 73	            return null;
 74	        }
 75	
 76	        return buildTree(frequencies);
 77	    }
 78	
 79	    private static Node buildTree(int[] frequencies) {
 80	        PriorityQueue<Node> nodes = createLeafQueue(frequencies);
 81	
 82	        while (nodes.size() > 1) {
 83	            nodes.add(mergeLowestFrequencyNodes(nodes));
 84	        }
 85	
 86	        return nodes.poll();
 87	    }
 88	
 89	    private static PriorityQueue<Node> createLeafQueue(int[] frequencies) {
 90	        PriorityQueue<Node> nodes = new PriorityQueue<>(NODE_ORDER);
 91	
 92	        for (int i = 0; i < frequencies.length; i++) {
 93	            nodes.add(new Node(frequencies[i], i));
 94	        }
 95	
 96	        return nodes;
 97	    }
 98	
 99	    private static Node mergeLowestFrequencyNodes(PriorityQueue<Node> nodes) {
100	        Node left = nodes.poll();
101	        Node right = nodes.poll();
102	        return new Node(left, right);
103	    }
104	
105	    private static ArrayList<String> collectCodesInTraversalOrder(Node root, int symbolCount) {
106	        ArrayList<String> codes = new ArrayList<>(symbolCount);
107	        collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.add(code));
108	        return codes;
109	    }
110	
111	    private static ArrayList<String> collectCodesBySymbolOrder(Node root, int symbolCount) {
112	        ArrayList<String> codes = createEmptyCodeList(symbolCount);
113	        collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.set(leaf.symbolIndex, code));
114	        return codes;
115	    }
116	
117	    private static ArrayList<String> createEmptyCodeList(int size) {
118	        ArrayList<String> codes = new ArrayList<>(size);
119	
120	        for (int i = 0; i < size; i++) {
121	            codes.add("");
122	        }
123	
124	        return codes;
125	    }
126	
127	    private static void collectLeafCodes(Node root, StringBuilder prefix, LeafCodeConsumer consumer) {
128	        if (root == null) {
129	            return;
130	        }
131	
132	        if (root.isLeaf()) {
133	            consumer.accept(root, codeFor(prefix));
134	            return;
135	        }
136	
137	        appendBranchCode(root.left, '0', prefix, consumer);
138	        appendBranchCode(root.right, '1', prefix, consumer);
139	    }
140	
141	    private static void appendBranchCode(Node node, char bit, StringBuilder prefix, LeafCodeConsumer consumer) {
142	        prefix.append(bit);
143	        collectLeafCodes(node, prefix, consumer);
144	        prefix.setLength(prefix.length() - 1);
145	    }
146	
147	    private static String codeFor(StringBuilder prefix) {
148	        return prefix.length() == 0 ? SINGLE_SYMBOL_CODE : prefix.toString();
149	    }
150	
151	    public static void main(String[] args) {
152	        String s = "abcdef";
153	        int[] freq = {5, 9, 12, 13, 16, 45};
154	        ArrayList<String> codes = huffmanCodes(s, freq);
155	
156	        for (String code : codes) {
157	            System.out.print(code + " ");
158	        }
159	    }
160	}
